 fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self, ValueError>{
  c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits())?;
  let documents=entities(d,"en1997_document",8,DOCUMENT,c)?;if documents.len()!=1||!documents.contains_key(&1){return Err(invalid("EN1997 requires one identity-1 document"));}let r=documents[&1];
  let category=u8::try_from(r.integer(2)?).map_err(|e| invalid(e.to_string()))?;
  let footing_rows=entities(d,"en1997_footing",9,FOOTING,c)?;let pile_rows=entities(d,"en1997_pile",15,PILE,c)?;
  let mut loads=groups(entities(d,"en1997_foundation_load_case",11,LOAD,c)?,&footing_rows,c)?;let mut tests=groups(entities(d,"en1997_pile_test_profile",6,TEST,c)?,&pile_rows,c)?;
  let mut layers=Vec::new();for v in ordered(entities(d,"en1997_soil_layer",16,LAYER,c)?.into_values(),1,c)?{checkpoint(c,layers.len(),0)?;layers.push(SoilLayer{id:text(v,3,c)?,soil_type:text(v,4,c)?,depth_top:v.real(5)?,depth_bottom:v.real(6)?,gamma:v.real(7)?,gamma_prime:v.real(8)?,phi_prime_deg:v.real(9)?,cohesion_effective:v.real(10)?,cohesion_undrained:v.real(11)?,oedometric_modulus:v.real(12)?,poisson_ratio:v.real(13)?,cpt_qc:v.real(14)?,spt_n:v.real(15)?});}
  let mut footings=Vec::new();for v in ordered(footing_rows.into_values(),1,c)?{let mut load_cases=Vec::new();for a in ordered(loads.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?{checkpoint(c,load_cases.len(),0)?;load_cases.push(FoundationLoadCase{id:text(a,3,c)?,design_situation:text(a,4,c)?,vertical_permanent:a.real(5)?,vertical_variable:a.real(6)?,horizontal_permanent:a.real(7)?,horizontal_variable:a.real(8)?,moment_permanent:a.real(9)?,moment_variable:a.real(10)?});}footings.push(SpreadFoundation{id:text(v,3,c)?,width:v.real(4)?,length:v.real(5)?,embedment:v.real(6)?,base_inclination_deg:v.real(7)?,settlement_limit:v.real(8)?,load_cases});}
  let mut piles=Vec::new();for v in ordered(pile_rows.into_values(),1,c)?{let count=u32::try_from(v.integer(7)?).map_err(|e| invalid(e.to_string()))?;let mut test_profiles=Vec::new();for a in ordered(tests.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?{checkpoint(c,test_profiles.len(),0)?;test_profiles.push(PileTestProfile{id:text(a,3,c)?,shaft_resistance:a.real(4)?,base_resistance:a.real(5)?});}piles.push(Pile{id:text(v,3,c)?,pile_type:text(v,4,c)?,diameter:v.real(5)?,length:v.real(6)?,count,alpha_s:v.real(8)?,unit_shaft_resistance:v.real(9)?,unit_base_resistance:v.real(10)?,compression_permanent:v.real(11)?,compression_variable:v.real(12)?,tension_permanent:v.real(13)?,tension_variable:v.real(14)?,test_profiles});}
  let mut retaining_walls=Vec::new();for v in ordered(entities(d,"en1997_retaining_wall",18,WALL,c)?.into_values(),1,c)?{checkpoint(c,retaining_walls.len(),0)?;retaining_walls.push(RetainingWall{id:text(v,3,c)?,height:v.real(4)?,embedment:v.real(5)?,base_width:v.real(6)?,stem_thickness:v.real(7)?,backfill_phi_deg:v.real(8)?,backfill_gamma:v.real(9)?,wall_friction_deg:v.real(10)?,earth_pressure_mode:text(v,11,c)?,wall_movement:text(v,12,c)?,ocr:v.real(13)?,concrete_gamma:v.real(14)?,surcharge:v.real(15)?,vertical_permanent:v.real(16)?,horizontal_permanent:v.real(17)?});}
  let mut slopes=Vec::new();for v in ordered(entities(d,"en1997_slope",8,SLOPE,c)?.into_values(),1,c)?{checkpoint(c,slopes.len(),0)?;slopes.push(Slope{id:text(v,3,c)?,angle_deg:v.real(4)?,height:v.real(5)?,length:v.real(6)?,governing_layer_id:text(v,7,c)?});}
  let mut uplift_cases=Vec::new();for v in ordered(entities(d,"en1997_uplift_case",9,UPLIFT,c)?.into_values(),1,c)?{checkpoint(c,uplift_cases.len(),0)?;uplift_cases.push(UpliftCase{id:text(v,3,c)?,permanent_stabilizing:v.real(4)?,permanent_destabilizing:v.real(5)?,variable_destabilizing:v.real(6)?,pore_pressure:v.real(7)?,total_stress:v.real(8)?});}
  let result=Self{structure_id:text(r,1,c)?,geotechnical_category:category,design_situation:text(r,3,c)?,design_approach:text(r,4,c)?,annex:read_annex(r.text(5)?)?,groundwater_level:r.real(6)?,investigation_depth:r.real(7)?,layers,footings,piles,retaining_walls,slopes,uplift_cases};c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(result)
 }
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,_d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.norm.en1997"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(invalid("EN1997 owned dialect differs")));}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1).map_err(store::io_schema::IoError::from_value_error)?;Ok(store::io_schema::IoOutcome::clean(()))}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(), ValueError>{let mut b=NativeEncodingBound::new(c)?;let mut rows=1;for count in[self.layers.len(),self.footings.len(),self.piles.len(),self.retaining_walls.len(),self.slopes.len(),self.uplift_cases.len()]{admit_rows(&mut b,&mut rows,count)?;}for v in &self.footings{admit_rows(&mut b,&mut rows,v.load_cases.len())?;}for v in &self.piles{admit_rows(&mut b,&mut rows,v.test_profiles.len())?;}b.add(16384)?;for s in[&self.structure_id,&self.design_situation,&self.design_approach]{b.repeated(s.len(),24)?;}for v in &self.layers{b.add(32768)?;for s in[&v.id,&v.soil_type]{b.repeated(s.len(),24)?;}}for v in &self.footings{b.add(16384)?;b.repeated(v.id.len(),24)?;for a in &v.load_cases{b.add(16384)?;for s in[&a.id,&a.design_situation]{b.repeated(s.len(),24)?;}}}for v in &self.piles{b.add(32768)?;for s in[&v.id,&v.pile_type]{b.repeated(s.len(),24)?;}for a in &v.test_profiles{b.add(8192)?;b.repeated(a.id.len(),24)?;}}for v in &self.retaining_walls{b.add(32768)?;for s in[&v.id,&v.earth_pressure_mode,&v.wall_movement]{b.repeated(s.len(),24)?;}}for v in &self.slopes{b.add(8192)?;for s in[&v.id,&v.governing_layer_id]{b.repeated(s.len(),24)?;}}for v in &self.uplift_cases{b.add(16384)?;b.repeated(v.id.len(),24)?;}b.finish()}
}
fn admit_rows(b:&mut NativeEncodingBound<'_,'_>,rows:&mut usize,add:usize)->Result<(), ValueError>{*rows=rows.checked_add(add).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "EN1997 native row count overflow"))?;b.check_rows(*rows)?;b.checkpoint()}

/// 📏️ Checks exact geotechnical SQL cell bytes without materializing projected rows.
struct NativeSemanticExtent { bytes:usize, rows:usize, limits:store::sqlite_snapshot::SqliteDatabaseLimits }
impl NativeSemanticExtent {
 fn new(limits:store::sqlite_snapshot::SqliteDatabaseLimits)->Self{Self{bytes:0,rows:0,limits}}
 fn add(&mut self,count:usize)->Result<(),ValueError>{self.bytes=self.bytes.checked_add(count).filter(|next|*next<=self.limits.max_value_bytes).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"EN1997 native semantic value bytes exceed caller limit"))?;Ok(())}
 fn begin_row(&mut self,fixed:usize)->Result<(),ValueError>{self.rows=self.rows.checked_add(1).filter(|next|*next<=self.limits.max_rows).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"EN1997 native semantic rows exceed caller limit"))?;self.add(fixed)}
 fn row(&mut self,fixed:usize,text:&[&str],numbers:&[f64])->Result<(),ValueError>{self.begin_row(fixed)?;for value in text{self.add(value.len())?;}for value in numbers{self.add(native_float_bytes(*value))?;}Ok(())}
 fn record(&mut self,record:&semio_framework_dsl_record::RecordValue,depth:usize,native:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<(),ValueError>{
  use semio_framework_dsl_record::FieldValue;
  if depth>2{return Err(invalid("EN1997 native entity nesting differs"))}
  self.begin_row(if depth==0{8}else{24})?;if self.rows%256==0{native.checkpoint()?;}
  for(id,value)in &record.fields{match value{
   FieldValue::UInt(_)=>self.add(8)?,
   FieldValue::Text(value)=>self.add(value.len())?,
   FieldValue::Float(value)=>self.add(native_float_bytes(*value))?,
   FieldValue::Enum(tag)if depth==0&&*id==4&&*tag<=1=>self.add(2)?,
   FieldValue::List(values)=>for value in values{let FieldValue::Record(child)=value else{return Err(invalid("EN1997 native entity list differs"))};self.record(child,depth+1,native)?;},
   _=>return Err(invalid("EN1997 native scalar shape differs")),
  }}Ok(())
 }
}
fn native_float_bytes(value:f64)->usize{if value.is_nan(){11}else if value.is_infinite(){32}else{22}}
fn admit_native_snapshot(snapshot:&En1997Snapshot,c:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 let mut extent=NativeSemanticExtent::new(c.limits());c.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;
 let mut row=|fixed,text:&[&str],numbers:&[f64]|->Result<(),ValueError>{extent.row(fixed,text,numbers)?;if extent.rows%256==0{c.checkpoint(SqliteSnapshotPhase::EncodeNative,extent.rows,0)?;}Ok(())};
 row(16,&[&snapshot.structure_id,&snapshot.design_situation,&snapshot.design_approach,annex(snapshot.annex)],&[snapshot.groundwater_level,snapshot.investigation_depth])?;
 for v in &snapshot.layers{row(24,&[&v.id,&v.soil_type],&[v.depth_top,v.depth_bottom,v.gamma,v.gamma_prime,v.phi_prime_deg,v.cohesion_effective,v.cohesion_undrained,v.oedometric_modulus,v.poisson_ratio,v.cpt_qc,v.spt_n])?;}
 for v in &snapshot.footings{row(24,&[&v.id],&[v.width,v.length,v.embedment,v.base_inclination_deg,v.settlement_limit])?;for a in &v.load_cases{row(24,&[&a.id,&a.design_situation],&[a.vertical_permanent,a.vertical_variable,a.horizontal_permanent,a.horizontal_variable,a.moment_permanent,a.moment_variable])?;}}
 for v in &snapshot.piles{row(32,&[&v.id,&v.pile_type],&[v.diameter,v.length,v.alpha_s,v.unit_shaft_resistance,v.unit_base_resistance,v.compression_permanent,v.compression_variable,v.tension_permanent,v.tension_variable])?;for a in &v.test_profiles{row(24,&[&a.id],&[a.shaft_resistance,a.base_resistance])?;}}
 for v in &snapshot.retaining_walls{row(24,&[&v.id,&v.earth_pressure_mode,&v.wall_movement],&[v.height,v.embedment,v.base_width,v.stem_thickness,v.backfill_phi_deg,v.backfill_gamma,v.wall_friction_deg,v.ocr,v.concrete_gamma,v.surcharge,v.vertical_permanent,v.horizontal_permanent])?;}
 for v in &snapshot.slopes{row(24,&[&v.id,&v.governing_layer_id],&[v.angle_deg,v.height,v.length])?;}
 for v in &snapshot.uplift_cases{row(24,&[&v.id],&[v.permanent_stabilizing,v.permanent_destabilizing,v.variable_destabilizing,v.pore_pressure,v.total_stress])?;}
 c.checkpoint(SqliteSnapshotPhase::EncodeNative,extent.rows,extent.rows)
}
